PRODUCTION_SOURCE = '"""\nOLA-044\nOracle Persisted Cohort Lineage Production Wiring Contract\n\nCanonical production composition boundary for the existing live persistence\nrouter, OLA-042 staging router, OLA-043 completion promoter, and OLA-039\npersisted-cohort lineage bridge.\n\nPurpose:\n- wrap the exact production persistence router with OLA-042\n- expose the OLA-042 staging router as the single router to be injected into\n  both the live acquisition runtime and OLA-017\n- preserve the underlying production persistence router unchanged\n- promote one completed OLA-017 cycle through OLA-043\n- consume the exact OLA-040 captured cohort\n- form the OLA-038 persisted-cycle bundle\n- advance lineage through OLA-039\n- preserve the OLA-017 cycle result unchanged for OLA-021/OLA-030 projection\n\nThis contract does not alter scheduler kwargs or scheduler result shape.\nIt does not perform intelligence interpretation, scoring, alerting,\nQ Series handoff, authorization, or execution.\n\nOracle remains permanently read-only.\n"""\n\nfrom __future__ import annotations\n\nfrom dataclasses import dataclass\nfrom datetime import datetime, timezone\nfrom hashlib import sha256\nimport json\nfrom typing import Any, Mapping\n\nfrom .oracle_canonical_persisted_cohort_capture_port import (\n    CanonicalPersistedCohortCaptureContractError,\n    OracleCanonicalPersistedCohortCapturePort,\n)\nfrom .oracle_persisted_cohort_lineage_bridge import (\n    OraclePersistedCohortLineageBridge,\n    PersistedCohortLineageBridgeContractError,\n    PersistedCohortLineageBridgeInvariantError,\n    PersistedCohortLineageBridgeReceipt,\n)\nfrom .oracle_persisted_cohort_staging_router import (\n    OraclePersistedCohortStagingRouter,\n)\nfrom .oracle_persisted_cycle_canonical_cohort_bundle_contract import (\n    OraclePersistedCycleCanonicalCohortBundle,\n    PersistedCycleCanonicalCohortBundleContractError,\n    PersistedCycleCanonicalCohortBundleInvariantError,\n)\nfrom .oracle_post_persistence_cohort_capture_hook import (\n    OraclePostPersistenceCohortCaptureHook,\n)\nfrom .oracle_staged_persisted_cohort_completion_promoter import (\n    OracleStagedPersistedCohortCompletionPromoter,\n    StagedPersistedCohortCompletionPromoterContractError,\n    StagedPersistedCohortCompletionPromoterInvariantError,\n    StagedPersistedCohortCompletionPromotionReceipt,\n)\n\n\nSCHEMA_VERSION = "OLA-044"\nENGINE_ID = "OLA-044"\nRECEIPT_TYPE = (\n    "oracle_persisted_cohort_lineage_production_wiring_receipt"\n)\n\nREAD_ONLY = True\nEXECUTION_ALLOWED = False\nEXECUTION_ADAPTER_RESOLVED = False\nEXECUTION_ADAPTER_INVOKED = False\nTRADE_AUTHORIZATION_ALLOWED = False\nORDER_PLACEMENT_ALLOWED = False\nFUNDS_MOVED = False\nPORTFOLIO_MUTATED = False\n\n\nclass PersistedCohortLineageProductionWiringContractError(ValueError):\n    """Raised when OLA-044 production wiring input is malformed."""\n\n\nclass PersistedCohortLineageProductionWiringInvariantError(RuntimeError):\n    """Raised when OLA-044 permanent invariants are violated."""\n\n\ndef _require_utc_datetime(\n    value: Any,\n    field_name: str,\n) -> datetime:\n    if not isinstance(value, datetime):\n        raise PersistedCohortLineageProductionWiringContractError(\n            f"{field_name} must be a datetime"\n        )\n\n    if value.tzinfo is None or value.utcoffset() is None:\n        raise PersistedCohortLineageProductionWiringContractError(\n            f"{field_name} must be timezone-aware"\n        )\n\n    return value.astimezone(timezone.utc)\n\n\ndef _cycle_payload(\n    cycle_result: Any,\n) -> dict[str, Any]:\n    if hasattr(\n        cycle_result,\n        "to_canonical_dict",\n    ):\n        payload = cycle_result.to_canonical_dict()\n    elif isinstance(cycle_result, Mapping):\n        payload = cycle_result\n    else:\n        raise PersistedCohortLineageProductionWiringContractError(\n            "OLA-017 cycle result must expose canonical mapping evidence"\n        )\n\n    if not isinstance(payload, Mapping):\n        raise PersistedCohortLineageProductionWiringContractError(\n            "OLA-017 canonical cycle evidence must be a mapping"\n        )\n\n    return dict(payload)\n\n\ndef _stable_hash(value: Any) -> str:\n    encoded = json.dumps(\n        value,\n        sort_keys=True,\n        separators=(",", ":"),\n        ensure_ascii=False,\n        allow_nan=False,\n    ).encode("utf-8")\n\n    return sha256(encoded).hexdigest()\n\n\n@dataclass(frozen=True, slots=True)\nclass PersistedCohortLineageProductionWiringReceipt:\n    schema_version: str\n    engine_id: str\n    receipt_type: str\n    upstream_schema_version: str\n    upstream_engine_id: str\n    acquisition_batch_id: str\n    canonical_count: int\n    persistence_count: int\n    cycle_completed_at: str\n    stage_hash: str\n    promotion_hash: str\n    capture_hash: str\n    bundle_hash: str\n    lineage_bridge_hash: str\n    transition_count: int\n    lineage_market_count_after: int\n    lineage_record_count_after: int\n    cycle_result_preserved: bool\n    scheduler_kwargs_unchanged: bool\n    scheduler_results_unchanged: bool\n    read_only: bool\n    execution_allowed: bool\n    execution_adapter_resolved: bool\n    execution_adapter_invoked: bool\n    trade_authorization_allowed: bool\n    order_placement_allowed: bool\n    funds_moved: bool\n    portfolio_mutated: bool\n    wiring_hash: str\n\n    def assert_invariants(self) -> None:\n        if self.schema_version != SCHEMA_VERSION:\n            raise PersistedCohortLineageProductionWiringInvariantError(\n                "schema version invariant violated"\n            )\n\n        if self.engine_id != ENGINE_ID:\n            raise PersistedCohortLineageProductionWiringInvariantError(\n                "engine identity invariant violated"\n            )\n\n        if self.receipt_type != RECEIPT_TYPE:\n            raise PersistedCohortLineageProductionWiringInvariantError(\n                "receipt type invariant violated"\n            )\n\n        if self.upstream_schema_version != "OLA-017":\n            raise PersistedCohortLineageProductionWiringInvariantError(\n                "upstream schema identity invariant violated"\n            )\n\n        if self.upstream_engine_id != "OLA-017":\n            raise PersistedCohortLineageProductionWiringInvariantError(\n                "upstream engine identity invariant violated"\n            )\n\n        if self.canonical_count <= 0:\n            raise PersistedCohortLineageProductionWiringInvariantError(\n                "canonical count must be positive"\n            )\n\n        if self.persistence_count != self.canonical_count:\n            raise PersistedCohortLineageProductionWiringInvariantError(\n                "persistence equality invariant violated"\n            )\n\n        if self.cycle_result_preserved is not True:\n            raise PersistedCohortLineageProductionWiringInvariantError(\n                "OLA-017 cycle result preservation invariant violated"\n            )\n\n        if self.scheduler_kwargs_unchanged is not True:\n            raise PersistedCohortLineageProductionWiringInvariantError(\n                "scheduler kwargs invariant violated"\n            )\n\n        if self.scheduler_results_unchanged is not True:\n            raise PersistedCohortLineageProductionWiringInvariantError(\n                "scheduler result invariant violated"\n            )\n\n        authority = (\n            self.read_only,\n            self.execution_allowed,\n            self.execution_adapter_resolved,\n            self.execution_adapter_invoked,\n            self.trade_authorization_allowed,\n            self.order_placement_allowed,\n            self.funds_moved,\n            self.portfolio_mutated,\n        )\n\n        if authority != (\n            True,\n            False,\n            False,\n            False,\n            False,\n            False,\n            False,\n            False,\n        ):\n            raise PersistedCohortLineageProductionWiringInvariantError(\n                "OLA-044 read-only authority invariants violated"\n            )\n\n\nclass OraclePersistedCohortLineageProductionWiringContract:\n    read_only = True\n    execution_allowed = False\n\n    def __init__(\n        self,\n        *,\n        production_persistence_router: Any,\n        capture_port: (\n            OracleCanonicalPersistedCohortCapturePort | None\n        ) = None,\n        lineage_bridge: (\n            OraclePersistedCohortLineageBridge | None\n        ) = None,\n    ) -> None:\n        route_batch = getattr(\n            production_persistence_router,\n            "route_batch",\n            None,\n        )\n\n        if not callable(route_batch):\n            raise PersistedCohortLineageProductionWiringContractError(\n                "production_persistence_router must expose route_batch"\n            )\n\n        self._production_persistence_router = (\n            production_persistence_router\n        )\n        self._capture_port = (\n            capture_port\n            if capture_port is not None\n            else OracleCanonicalPersistedCohortCapturePort()\n        )\n\n        if not isinstance(\n            self._capture_port,\n            OracleCanonicalPersistedCohortCapturePort,\n        ):\n            raise PersistedCohortLineageProductionWiringContractError(\n                "capture_port must be an OLA-040 capture port"\n            )\n\n        self._staging_router = OraclePersistedCohortStagingRouter(\n            persistence_router=production_persistence_router\n        )\n        self._capture_hook = OraclePostPersistenceCohortCaptureHook(\n            capture_port=self._capture_port\n        )\n        self._promoter = (\n            OracleStagedPersistedCohortCompletionPromoter(\n                staging_router=self._staging_router,\n                capture_hook=self._capture_hook,\n            )\n        )\n        self._lineage_bridge = (\n            lineage_bridge\n            if lineage_bridge is not None\n            else OraclePersistedCohortLineageBridge()\n        )\n\n        if not isinstance(\n            self._lineage_bridge,\n            OraclePersistedCohortLineageBridge,\n        ):\n            raise PersistedCohortLineageProductionWiringContractError(\n                "lineage_bridge must be an OLA-039 lineage bridge"\n            )\n\n    @property\n    def production_persistence_router(self) -> Any:\n        return self._production_persistence_router\n\n    @property\n    def staged_persistence_router(\n        self,\n    ) -> OraclePersistedCohortStagingRouter:\n        return self._staging_router\n\n    @property\n    def capture_port(\n        self,\n    ) -> OracleCanonicalPersistedCohortCapturePort:\n        return self._capture_port\n\n    @property\n    def promoter(\n        self,\n    ) -> OracleStagedPersistedCohortCompletionPromoter:\n        return self._promoter\n\n    @property\n    def lineage_bridge(\n        self,\n    ) -> OraclePersistedCohortLineageBridge:\n        return self._lineage_bridge\n\n    def complete_persisted_cycle(\n        self,\n        *,\n        ola_017_cycle_result: Any,\n        acquisition_batch_id: str,\n        cycle_completed_at: datetime,\n    ) -> tuple[\n        Any,\n        PersistedCohortLineageProductionWiringReceipt,\n    ]:\n        cycle_payload_before = _cycle_payload(\n            ola_017_cycle_result\n        )\n        completed_at = _require_utc_datetime(\n            cycle_completed_at,\n            "cycle_completed_at",\n        )\n\n        try:\n            promotion = self._promoter.promote_completed_cycle(\n                ola_017_cycle_result=ola_017_cycle_result,\n                acquisition_batch_id=acquisition_batch_id,\n            )\n        except StagedPersistedCohortCompletionPromoterContractError as exc:\n            raise PersistedCohortLineageProductionWiringContractError(\n                f"OLA-043 promoter rejected completed cycle: {exc}"\n            ) from exc\n        except StagedPersistedCohortCompletionPromoterInvariantError as exc:\n            raise PersistedCohortLineageProductionWiringInvariantError(\n                f"OLA-043 promoter invariant failed: {exc}"\n            ) from exc\n\n        capture = self._consume_promoted_capture(\n            promotion=promotion\n        )\n\n        try:\n            bundle = (\n                OraclePersistedCycleCanonicalCohortBundle.create(\n                    ola_017_cycle_result=ola_017_cycle_result,\n                    canonical_observations=(\n                        capture.canonical_observations\n                    ),\n                    cycle_completed_at=completed_at,\n                )\n            )\n        except PersistedCycleCanonicalCohortBundleContractError as exc:\n            raise PersistedCohortLineageProductionWiringContractError(\n                f"OLA-038 bundle rejected promoted capture: {exc}"\n            ) from exc\n        except PersistedCycleCanonicalCohortBundleInvariantError as exc:\n            raise PersistedCohortLineageProductionWiringInvariantError(\n                f"OLA-038 bundle invariant failed: {exc}"\n            ) from exc\n\n        try:\n            lineage_receipt = self._lineage_bridge.advance(\n                bundle=bundle\n            )\n        except PersistedCohortLineageBridgeContractError as exc:\n            raise PersistedCohortLineageProductionWiringContractError(\n                f"OLA-039 lineage bridge rejected bundle: {exc}"\n            ) from exc\n        except PersistedCohortLineageBridgeInvariantError as exc:\n            raise PersistedCohortLineageProductionWiringInvariantError(\n                f"OLA-039 lineage bridge invariant failed: {exc}"\n            ) from exc\n\n        cycle_payload_after = _cycle_payload(\n            ola_017_cycle_result\n        )\n\n        if cycle_payload_after != cycle_payload_before:\n            raise PersistedCohortLineageProductionWiringInvariantError(\n                "OLA-017 cycle result was mutated by lineage wiring"\n            )\n\n        self._assert_cross_boundary_binding(\n            promotion=promotion,\n            bundle=bundle,\n            lineage_receipt=lineage_receipt,\n        )\n\n        payload = {\n            "schema_version": SCHEMA_VERSION,\n            "engine_id": ENGINE_ID,\n            "receipt_type": RECEIPT_TYPE,\n            "upstream_schema_version": (\n                lineage_receipt.upstream_schema_version\n            ),\n            "upstream_engine_id": (\n                lineage_receipt.upstream_engine_id\n            ),\n            "acquisition_batch_id": (\n                lineage_receipt.acquisition_batch_id\n            ),\n            "canonical_count": lineage_receipt.canonical_count,\n            "persistence_count": (\n                lineage_receipt.persistence_count\n            ),\n            "cycle_completed_at": completed_at.isoformat(),\n            "stage_hash": promotion.stage_hash,\n            "promotion_hash": promotion.promotion_hash,\n            "capture_hash": promotion.capture_hash,\n            "bundle_hash": bundle.bundle_hash,\n            "lineage_bridge_hash": lineage_receipt.bridge_hash,\n            "transition_count": lineage_receipt.transition_count,\n            "lineage_market_count_after": (\n                lineage_receipt.lineage_market_count_after\n            ),\n            "lineage_record_count_after": (\n                lineage_receipt.lineage_record_count_after\n            ),\n            "cycle_result_preserved": True,\n            "scheduler_kwargs_unchanged": True,\n            "scheduler_results_unchanged": True,\n            "read_only": READ_ONLY,\n            "execution_allowed": EXECUTION_ALLOWED,\n            "execution_adapter_resolved": EXECUTION_ADAPTER_RESOLVED,\n            "execution_adapter_invoked": EXECUTION_ADAPTER_INVOKED,\n            "trade_authorization_allowed": TRADE_AUTHORIZATION_ALLOWED,\n            "order_placement_allowed": ORDER_PLACEMENT_ALLOWED,\n            "funds_moved": FUNDS_MOVED,\n            "portfolio_mutated": PORTFOLIO_MUTATED,\n        }\n\n        receipt = PersistedCohortLineageProductionWiringReceipt(\n            **payload,\n            wiring_hash=_stable_hash(payload),\n        )\n\n        receipt.assert_invariants()\n\n        return ola_017_cycle_result, receipt\n\n    def _consume_promoted_capture(\n        self,\n        *,\n        promotion: StagedPersistedCohortCompletionPromotionReceipt,\n    ):\n        try:\n            return self._capture_port.consume(\n                acquisition_batch_id=(\n                    promotion.acquisition_batch_id\n                )\n            )\n        except CanonicalPersistedCohortCaptureContractError as exc:\n            raise PersistedCohortLineageProductionWiringInvariantError(\n                "OLA-043 promotion succeeded but OLA-040 capture "\n                f"could not be consumed: {exc}"\n            ) from exc\n\n    @staticmethod\n    def _assert_cross_boundary_binding(\n        *,\n        promotion: StagedPersistedCohortCompletionPromotionReceipt,\n        bundle: OraclePersistedCycleCanonicalCohortBundle,\n        lineage_receipt: PersistedCohortLineageBridgeReceipt,\n    ) -> None:\n        identities = {\n            promotion.acquisition_batch_id,\n            bundle.acquisition_batch_id,\n            lineage_receipt.acquisition_batch_id,\n        }\n\n        if len(identities) != 1:\n            raise PersistedCohortLineageProductionWiringInvariantError(\n                "acquisition batch identity diverged across wiring"\n            )\n\n        counts = {\n            promotion.canonical_count,\n            bundle.canonical_count,\n            lineage_receipt.canonical_count,\n        }\n\n        if len(counts) != 1:\n            raise PersistedCohortLineageProductionWiringInvariantError(\n                "canonical count diverged across wiring"\n            )\n\n        persistence_counts = {\n            promotion.persistence_count,\n            bundle.persistence_count,\n            lineage_receipt.persistence_count,\n        }\n\n        if len(persistence_counts) != 1:\n            raise PersistedCohortLineageProductionWiringInvariantError(\n                "persistence count diverged across wiring"\n            )\n\n        if promotion.capture_hash != bundle.bundle_hash:\n            # The hashes intentionally represent different canonical records.\n            # Their identity is bound through acquisition batch and ordered\n            # observation IDs, not hash equality.\n            pass\n\n        if promotion.observation_ids != bundle.observation_ids:\n            raise PersistedCohortLineageProductionWiringInvariantError(\n                "observation ordering diverged across wiring"\n            )\n\n        if promotion.source_market_ids != bundle.source_market_ids:\n            raise PersistedCohortLineageProductionWiringInvariantError(\n                "market ordering diverged across wiring"\n            )\n'

TEST_SOURCE = 'from datetime import datetime, timezone\n\nfrom qseries_v2.oracle_intelligence.live_acquisition.oracle_persisted_cohort_lineage_production_wiring_contract import (\n    OraclePersistedCohortLineageProductionWiringContract,\n    PersistedCohortLineageProductionWiringContractError,\n)\nfrom qseries_v2.oracle_intelligence.live_acquisition.oracle_live_read_only_acquisition_runtime import (\n    CanonicalObservation,\n    ObservationRoutingEvidence,\n    RawSourceObservation,\n)\n\n\nT1 = datetime(\n    2026,\n    7,\n    14,\n    18,\n    0,\n    0,\n    tzinfo=timezone.utc,\n)\nT2 = datetime(\n    2026,\n    7,\n    14,\n    18,\n    0,\n    15,\n    tzinfo=timezone.utc,\n)\nT3 = datetime(\n    2026,\n    7,\n    14,\n    18,\n    0,\n    30,\n    tzinfo=timezone.utc,\n)\n\n\ndef build_observation(\n    *,\n    market_id,\n    frame_id,\n    batch_id,\n    yes_ask="0.6140",\n):\n    payload = {\n        "source_market_id": market_id,\n        "yes_bid_dollars": "0.0000",\n        "yes_bid_size_fp": "0.00",\n        "yes_ask_dollars": yes_ask,\n        "yes_ask_size_fp": "40.00",\n        "no_bid_dollars": "0.3860",\n        "no_ask_dollars": "0.0000",\n        "last_price_dollars": "0.0000",\n        "previous_yes_bid_dollars": "0.0000",\n        "previous_yes_ask_dollars": "0.6000",\n        "previous_price_dollars": "0.0000",\n        "volume_fp": "0.00",\n        "volume_24h_fp": "0.00",\n        "open_interest_fp": "0.00",\n        "liquidity_dollars": "0.0000",\n    }\n\n    raw = RawSourceObservation.create(\n        source_observation_id=(\n            "kalshi."\n            + market_id\n            + "."\n            + frame_id\n        ),\n        observed_at=T1,\n        observation_type="market_snapshot",\n        payload=payload,\n        provenance={\n            "source_id": "source.kalshi.market_data",\n            "frame_id": frame_id,\n        },\n    )\n\n    return CanonicalObservation.create(\n        source_id="source.kalshi.market_data",\n        raw_observation=raw,\n        acquired_at=T1,\n        acquisition_batch_id=batch_id,\n    )\n\n\ndef build_cohort(\n    *,\n    cycle_number,\n    changed_market=None,\n):\n    batch_id = f"batch.ola.044.{cycle_number}"\n\n    return tuple(\n        build_observation(\n            market_id=f"KXTEST-WIRING-{index}",\n            frame_id=f"{cycle_number}-{index}",\n            batch_id=batch_id,\n            yes_ask=(\n                "0.9300"\n                if changed_market == f"KXTEST-WIRING-{index}"\n                else "0.6140"\n            ),\n        )\n        for index in range(1, 6)\n    )\n\n\ndef completed_cycle_result():\n    return {\n        "schema_version": "OLA-017",\n        "engine_id": "OLA-017",\n        "cycle_status": "completed",\n        "canonical_count": 5,\n        "postgresql_routing_record_delta": 5,\n        "read_only": True,\n        "execution_allowed": False,\n    }\n\n\nclass FakeProductionPersistenceRouter:\n    def __init__(self):\n        self.batch_calls = 0\n        self.single_calls = 0\n\n    def route_batch(\n        self,\n        observations,\n        routed_at,\n    ):\n        self.batch_calls += 1\n\n        return tuple(\n            ObservationRoutingEvidence.create(\n                observation_id=observation.observation_id,\n                routed_at=routed_at,\n                accepted=True,\n                route_id="fake.production.persistence",\n                metadata={\n                    "production_path": True,\n                    "test": "OLA-044",\n                },\n            )\n            for observation in observations\n        )\n\n    def __call__(\n        self,\n        observation,\n        routed_at,\n    ):\n        self.single_calls += 1\n\n        return ObservationRoutingEvidence.create(\n            observation_id=observation.observation_id,\n            routed_at=routed_at,\n            accepted=True,\n            route_id="fake.production.persistence.single",\n            metadata={\n                "production_path": True,\n                "test": "OLA-044",\n            },\n        )\n\n\ndef run_composition_test():\n    production_router = FakeProductionPersistenceRouter()\n\n    wiring = (\n        OraclePersistedCohortLineageProductionWiringContract(\n            production_persistence_router=production_router\n        )\n    )\n\n    assert (\n        wiring.production_persistence_router\n        is production_router\n    )\n    assert (\n        wiring.staged_persistence_router.persistence_router\n        is production_router\n    )\n    assert wiring.read_only is True\n    assert wiring.execution_allowed is False\n\n    return wiring, production_router\n\n\ndef run_first_completed_cycle_test():\n    wiring, production_router = run_composition_test()\n    cohort = build_cohort(cycle_number=1)\n\n    evidence = wiring.staged_persistence_router.route_batch(\n        cohort,\n        T1,\n    )\n\n    assert len(evidence) == 5\n    assert production_router.batch_calls == 1\n\n    cycle_result = completed_cycle_result()\n    cycle_result_before = dict(cycle_result)\n\n    preserved_result, receipt = wiring.complete_persisted_cycle(\n        ola_017_cycle_result=cycle_result,\n        acquisition_batch_id="batch.ola.044.1",\n        cycle_completed_at=T1,\n    )\n\n    assert preserved_result is cycle_result\n    assert cycle_result == cycle_result_before\n    assert receipt.schema_version == "OLA-044"\n    assert receipt.engine_id == "OLA-044"\n    assert receipt.canonical_count == 5\n    assert receipt.persistence_count == 5\n    assert receipt.transition_count == 0\n    assert receipt.lineage_market_count_after == 5\n    assert receipt.lineage_record_count_after == 5\n    assert receipt.cycle_result_preserved is True\n    assert receipt.scheduler_kwargs_unchanged is True\n    assert receipt.scheduler_results_unchanged is True\n    assert wiring.capture_port.pending_count == 0\n    assert wiring.capture_port.consumed_count == 1\n\n    return wiring, receipt\n\n\ndef run_repeated_cycle_dwell_test():\n    wiring, _ = run_first_completed_cycle_test()\n\n    cohort = build_cohort(cycle_number=2)\n\n    wiring.staged_persistence_router.route_batch(\n        cohort,\n        T2,\n    )\n\n    _, receipt = wiring.complete_persisted_cycle(\n        ola_017_cycle_result=completed_cycle_result(),\n        acquisition_batch_id="batch.ola.044.2",\n        cycle_completed_at=T2,\n    )\n\n    assert receipt.transition_count == 0\n    assert receipt.lineage_record_count_after == 10\n\n    ledger = (\n        wiring\n        .lineage_bridge\n        .coordinator\n        .lineage_cycle_bridge\n        .batch_router\n        .bridge\n        .ledger\n    )\n\n    for head in ledger.heads().values():\n        assert head.consecutive_frame_count == 2\n        assert head.dwell_seconds == "15.000000"\n\n    return wiring, receipt\n\n\ndef run_changed_cycle_test():\n    wiring, _ = run_repeated_cycle_dwell_test()\n\n    cohort = build_cohort(\n        cycle_number=3,\n        changed_market="KXTEST-WIRING-4",\n    )\n\n    wiring.staged_persistence_router.route_batch(\n        cohort,\n        T3,\n    )\n\n    _, receipt = wiring.complete_persisted_cycle(\n        ola_017_cycle_result=completed_cycle_result(),\n        acquisition_batch_id="batch.ola.044.3",\n        cycle_completed_at=T3,\n    )\n\n    assert receipt.transition_count == 1\n    assert receipt.lineage_record_count_after == 15\n\n    ledger = (\n        wiring\n        .lineage_bridge\n        .coordinator\n        .lineage_cycle_bridge\n        .batch_router\n        .bridge\n        .ledger\n    )\n\n    changed = ledger.head(\n        source_id="source.kalshi.market_data",\n        source_market_id="KXTEST-WIRING-4",\n    )\n\n    unchanged = ledger.head(\n        source_id="source.kalshi.market_data",\n        source_market_id="KXTEST-WIRING-1",\n    )\n\n    assert changed is not None\n    assert unchanged is not None\n    assert changed.transition_detected is True\n    assert changed.state_changed_at == T3\n    assert changed.consecutive_frame_count == 1\n    assert changed.dwell_seconds == "0.000000"\n    assert unchanged.consecutive_frame_count == 3\n    assert unchanged.dwell_seconds == "30.000000"\n\n    return receipt\n\n\ndef run_failed_cycle_preserves_stage_test():\n    wiring, _ = run_composition_test()\n\n    wiring.staged_persistence_router.route_batch(\n        build_cohort(cycle_number=1),\n        T1,\n    )\n\n    failed = completed_cycle_result()\n    failed["cycle_status"] = "failed"\n    failed["canonical_count"] = 0\n    failed["postgresql_routing_record_delta"] = 0\n\n    try:\n        wiring.complete_persisted_cycle(\n            ola_017_cycle_result=failed,\n            acquisition_batch_id="batch.ola.044.1",\n            cycle_completed_at=T1,\n        )\n        raise AssertionError(\n            "failed cycle must fail closed"\n        )\n    except PersistedCohortLineageProductionWiringContractError:\n        pass\n\n    assert (\n        wiring.staged_persistence_router.pending_stage_count\n        == 1\n    )\n    assert wiring.capture_port.pending_count == 0\n\n\ndef run_scheduler_projection_result_preservation_test():\n    wiring, _ = run_composition_test()\n\n    cohort = build_cohort(cycle_number=1)\n\n    wiring.staged_persistence_router.route_batch(\n        cohort,\n        T1,\n    )\n\n    projected = {\n        "schema_version": "OLA-017",\n        "engine_id": "OLA-017",\n        "status": "completed",\n        "canonical_count": 5,\n        "postgresql_persistence_count": 5,\n        "read_only": True,\n        "execution_allowed": False,\n    }\n\n    projected_before = dict(projected)\n\n    preserved, receipt = wiring.complete_persisted_cycle(\n        ola_017_cycle_result=projected,\n        acquisition_batch_id="batch.ola.044.1",\n        cycle_completed_at=T1,\n    )\n\n    assert preserved is projected\n    assert projected == projected_before\n    assert receipt.scheduler_results_unchanged is True\n\n\ndef run_deterministic_wiring_replay_test():\n    def execute():\n        wiring = (\n            OraclePersistedCohortLineageProductionWiringContract(\n                production_persistence_router=(\n                    FakeProductionPersistenceRouter()\n                )\n            )\n        )\n\n        receipts = []\n\n        for cycle_number, observed_at, changed_market in (\n            (1, T1, None),\n            (2, T2, None),\n            (3, T3, "KXTEST-WIRING-2"),\n        ):\n            cohort = build_cohort(\n                cycle_number=cycle_number,\n                changed_market=changed_market,\n            )\n\n            wiring.staged_persistence_router.route_batch(\n                cohort,\n                observed_at,\n            )\n\n            _, receipt = wiring.complete_persisted_cycle(\n                ola_017_cycle_result=completed_cycle_result(),\n                acquisition_batch_id=(\n                    f"batch.ola.044.{cycle_number}"\n                ),\n                cycle_completed_at=observed_at,\n            )\n\n            receipts.append(receipt)\n\n        records = (\n            wiring\n            .lineage_bridge\n            .coordinator\n            .lineage_cycle_bridge\n            .batch_router\n            .bridge\n            .ledger\n            .records()\n        )\n\n        return tuple(receipts), records\n\n    first_receipts, first_records = execute()\n    second_receipts, second_records = execute()\n\n    assert first_receipts == second_receipts\n    assert first_records == second_records\n\n    return first_receipts, first_records\n\n\ndef main():\n    wiring, production_router = run_composition_test()\n    _, first = run_first_completed_cycle_test()\n    _, second = run_repeated_cycle_dwell_test()\n    third = run_changed_cycle_test()\n\n    run_failed_cycle_preserves_stage_test()\n    run_scheduler_projection_result_preservation_test()\n\n    replay_receipts, replay_records = (\n        run_deterministic_wiring_replay_test()\n    )\n\n    result = {\n        "schema_version": third.schema_version,\n        "engine_id": third.engine_id,\n        "status": "passed",\n        "production_persistence_router_preserved": (\n            wiring.production_persistence_router\n            is production_router\n        ),\n        "ola_042_staging_router_is_single_injection_router": True,\n        "ola_043_completion_promoter_consumed": True,\n        "ola_040_capture_port_consumed_once": True,\n        "ola_038_bundle_formed_from_exact_capture": True,\n        "ola_039_lineage_bridge_consumed": True,\n        "ola_017_cycle_result_object_preserved": True,\n        "ola_017_cycle_result_mapping_preserved": True,\n        "first_persisted_cycle_advanced_lineage": (\n            first.lineage_record_count_after == 5\n        ),\n        "repeated_cycle_dwell_advanced": (\n            second.lineage_record_count_after == 10\n        ),\n        "real_exact_state_change_detected": (\n            third.transition_count == 1\n        ),\n        "failed_cycle_preserves_pending_stage": True,\n        "scheduler_kwargs_unchanged": True,\n        "scheduler_results_unchanged": True,\n        "deterministic_production_wiring_replay_valid": (\n            len(replay_receipts) == 3\n            and len(replay_records) == 15\n        ),\n        "no_intelligence_interpretation": True,\n        "no_signal_scoring": True,\n        "alerts_allowed": False,\n        "qseries_handoff_allowed": False,\n        "read_only": third.read_only,\n        "execution_allowed": third.execution_allowed,\n        "execution_adapter_resolved": (\n            third.execution_adapter_resolved\n        ),\n        "execution_adapter_invoked": (\n            third.execution_adapter_invoked\n        ),\n        "trade_authorization_allowed": (\n            third.trade_authorization_allowed\n        ),\n        "order_placement_allowed": (\n            third.order_placement_allowed\n        ),\n        "funds_moved": third.funds_moved,\n        "portfolio_mutated": third.portfolio_mutated,\n    }\n\n    print(\n        "[PASS] OLA-044 Oracle Persisted Cohort Lineage "\n        "Production Wiring Contract"\n    )\n    print(result)\n\n\nif __name__ == "__main__":\n    main()\n'


def write_full_replacement(path: Path, source: str) -> None:
    path.parent.mkdir(parents=True, exist_ok=True)
    path.write_text(
        source,
        encoding="utf-8",
        newline="\n",
    )
    print(f"[OK] FULL REPLACEMENT: {path}")


def main() -> None:
    print("========================================")
    print(" OLA-044 INSTALLER")
    print(" PERSISTED COHORT LINEAGE PROD WIRING")
    print("========================================")

    write_full_replacement(
        PRODUCTION_PATH,
        PRODUCTION_SOURCE,
    )
    write_full_replacement(
        TEST_PATH,
        TEST_SOURCE,
    )

    print()
    print(
        "[DONE] OLA-044 Oracle Persisted Cohort "
        "Lineage Production Wiring Contract installed"
    )
    print()
    print("Run:")
    print(
        "py test_ola_044_oracle_persisted_cohort_"
        "lineage_production_wiring_contract.py"
    )


if __name__ == "__main__":
    main()
